// 정산 관련 유틸리티 함수
import { Settlement } from '../types';

// 정산 금액 포맷팅 (null인 경우 0원으로 표시)
export const formatSettlementPrice = (price: number | null): string => {
  if (price === null) {
    return '0원';
  }
  return `${price.toLocaleString()}원`;
};

// 총 정산 금액 계산 (null은 0으로 처리)
export const calculateTotalSettlement = (settlements: Settlement[]): number => {
  return settlements.reduce((sum, settlement) => {
    return sum + (settlement.settlementPrice ?? 0);
  }, 0);
};

// null 값 표시 처리
export const getDisplayValue = (value: string | null): string => {
  return value === null ? '-' : value;
};

