import React, { useState } from 'react';
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { ManualCategory } from '../types';
import { reorderManualCategory } from '../utils/manualCategoryApi';
import { useToast } from '../hooks/useToast';

interface ManualCategoryReorderListProps {
  categories: ManualCategory[];
  onReorder?: () => void; // 순서 변경 후 목록 새로고침 콜백
}

interface SortableCategoryItemProps {
  category: ManualCategory;
}

const SortableCategoryItem: React.FC<SortableCategoryItemProps> = ({ category }) => {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: category.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div ref={setNodeRef} style={style}>
      <div className="flex items-center gap-3 bg-white rounded-lg shadow-sm p-4 border border-gray-200">
        <div
          {...attributes}
          {...listeners}
          className="cursor-grab active:cursor-grabbing text-gray-400 hover:text-gray-600"
          title="드래그하여 순서 변경"
        >
          <svg
            className="w-5 h-5"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M4 8h16M4 16h16"
            />
          </svg>
        </div>
        <div className="flex-1">
          <div className="font-semibold text-gray-900">{category.name}</div>
          <div className="text-sm text-gray-500">순서: {category.sortOrder}</div>
        </div>
      </div>
    </div>
  );
};

const ManualCategoryReorderList: React.FC<ManualCategoryReorderListProps> = ({
  categories,
  onReorder,
}) => {
  const [items, setItems] = useState<ManualCategory[]>(categories);
  const { showToast } = useToast();

  // sensors 설정
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  // categories prop이 변경되면 items 업데이트
  React.useEffect(() => {
    setItems(categories);
  }, [categories]);

  // 드래그 종료 핸들러
  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;

    if (!over || active.id === over.id) {
      return;
    }

    const oldIndex = items.findIndex((item) => item.id === active.id);
    const newIndex = items.findIndex((item) => item.id === over.id);

    if (oldIndex === -1 || newIndex === -1) {
      return;
    }

    // 범위 검증
    const totalActiveCategories = items.filter((item) => item.isActive).length;
    const newSortOrder = newIndex + 1; // 1부터 시작

    if (newSortOrder < 1 || newSortOrder > totalActiveCategories) {
      showToast('순서 범위를 벗어났습니다.', 'error');
      return;
    }

    // 낙관적 업데이트: UI를 먼저 업데이트
    const newItems = arrayMove(items, oldIndex, newIndex);
    setItems(newItems);

    // API 호출
    const movedCategory = newItems[newIndex];

    try {
      await reorderManualCategory(movedCategory.id, { newSortOrder });
      showToast('순서가 변경되었습니다.', 'success');
      // 순서 변경 후 목록 새로고침
      onReorder?.();
    } catch (error) {
      // 실패 시 원래 순서로 복구
      setItems(categories);
      showToast(
        error instanceof Error
          ? error.message
          : '순서 변경에 실패했습니다.',
        'error'
      );
    }
  };

  if (items.length === 0) {
    return (
      <div className="text-center py-8 text-gray-500">
        카테고리가 없습니다.
      </div>
    );
  }

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragEnd={handleDragEnd}
    >
      <SortableContext
        items={items.map((item) => item.id)}
        strategy={verticalListSortingStrategy}
      >
        <div className="space-y-2">
          {items
            .filter((cat) => cat.isActive)
            .map((category) => (
              <SortableCategoryItem key={category.id} category={category} />
            ))}
        </div>
      </SortableContext>
    </DndContext>
  );
};

export default ManualCategoryReorderList;
